cd /tmp/sv-d445ef72d2974e39b2fe5258bddc7d6d/symbols

# Find nearest symbol <= address (including zero-size symbols)
for addr in 222098 222234 19bac0 19bc14; do
  dec_addr=$((16#$addr))
  echo "=== 0x$addr ==="
  awk -v target="$dec_addr" '{
    addr = strtonum("0x"$1)
    size = strtonum($2)
    if (addr <= target) {
      # Check if within bounds (if size known) or just nearest
      if (size > 0 && target < addr + size) {
        printf "  EXACT: %s + 0x%x (size=0x%x)\n", $3, target - addr, size
      }
      # Track nearest regardless
      nearest_addr = addr
      nearest_name = $3
      nearest_off = target - addr
    }
  } END {
    if (nearest_name != "") printf "  NEAREST: %s + 0x%x\n", nearest_name, nearest_off
  }' monosgen_syms.txt
done

