{"command": "cd /tmp/sv-d445ef72d2974e39b2fe5258bddc7d6d/symbols

# The .so has 1517 exported functions. Let me try to resolve addresses using those.
# Sometimes the functions are small enough that exported symbols work.
# Let me get a sorted list of all defined FUNC symbols with their addresses

readelf -sW libmonosgen-2.0.so 2>/dev/null | awk '
  $4=="FUNC" && $7!="UND" && strtonum("0x"$2) > 0 {
    printf "0x%s %s %s\n", $2, $3, $8
  }' | sort > all_syms_sorted.txt

# For each target address, find the containing or nearest preceding symbol
python3 << 'EOF'
import sys

# Load symbols
syms = []
with open("all_syms_sorted.txt") as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3:
            addr = int(parts[0], 16)
            size = int(parts[1])
            name = parts[2]
            syms.append((addr, size, name))

syms.sort(key=lambda x: x[0])

targets = {
    "#01": 0x222098,
    "#02": 0x222234,
    "#03": 0x19bac0,
    "#06": 0x19bc14,
}

for frame, target in sorted(targets.items(), key=lambda x: x[0]):
    # Find nearest preceding symbol
    best = None
    for addr, size, name in syms:
        if addr <= target:
            best = (addr, size, name)
        else:
            break

    if best:
        addr, size, name = best
        offset = target - addr
        in_bounds = "✓" if (size > 0 and target < addr + size) else f"(nearest, +0x{offset:x} past)"
        if size > 0 and target < addr + size:
            print(f"  {frame} pc 0x{target:08x}: {name}+0x{offset:x} {in_bounds}")
        else:
            print(f"  {frame} pc 0x{target:08x}: {name}+0x{offset:x} {in_bounds}")
    else:
        print(f"  {frame} pc 0x{target:08x}: <unknown>")
EOF", "description": "Resolve addresses to symbols"}

